def sum_subarray_imbalances(nums):
    answer=0
    for left in range(len(nums)):
        seen=set();components=0
        for right in range(left,len(nums)):
            value=nums[right]
            if value not in seen:
                components+=1-(value-1 in seen)-(value+1 in seen);seen.add(value)
            answer+=components-1
    return answer

